require "rails_helper"

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  it "export refuses a recorded invoice number that exists only in the other seeded company" do
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    foreign_number = (Invoice.where(company_id: copper_kettle.id).pluck(:invoice_number) -
      Invoice.where(company_id: fork_and_leaf.id).pluck(:invoice_number)).compact.first
    expect(foreign_number).to be_present
    some_entry_id = TimesheetEntry.joins(project: :client).where(clients: { company_id: fork_and_leaf.id }).pick(:id)
    recorded["companies"]["Fork & Leaf Salads"] = recorded["companies"].fetch("Fork & Leaf Salads").merge(
      foreign_number => { "entry_ids" => [some_entry_id], "disposition" => "reserve" })
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    # "Resolve an invoice number only inside the named company. Refuse, never guess, when a number is missing, matches no invoice of that company, or would link an entry to another company's invoice."
    expect { source.export(generation: 3, captured_at: Time.utc(2026, 10, 25, 12)) }
      .to raise_error(Timekeeping::Handoff::LegacySource::Refused) { |error|
        expect(error.refusals.fetch(fork_and_leaf.id).join("\n")).to include(foreign_number.to_s)
        expect(error.refusals.fetch(copper_kettle.id, []).join("\n")).not_to include(foreign_number.to_s)
      }
  end
end

