require "rails_helper"

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  it "one refusal lists an orphan in one company and an unrecorded unlocked link in the other" do
    linked_ids = Timekeeping::SeedDispositionRecorder.snapshot(fork_and_leaf)[:links].pluck(:entry_id)
    orphan = TimesheetEntry.joins(project: :client).where(clients: { company_id: fork_and_leaf.id })
      .where.not(id: linked_ids).order(:id).first
    orphan.update_column(:locked, true)
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    dropped_number, = recorded["companies"].fetch("Copper Kettle Bakery").first
    recorded["companies"]["Copper Kettle Bakery"] = recorded["companies"]["Copper Kettle Bakery"].except(dropped_number)
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)

    # "Cutover proceeds only when the orphan, conflict and unlocked-link lists are empty, or every item has a recorded disposition."
    # Refuse with a per-company list of the items that have none: both companies appear in the one error.
    expect { source.export(generation: 3, captured_at: Time.utc(2026, 10, 25, 12)) }
      .to raise_error(Timekeeping::Handoff::Store::Error) { |error|
        expect(error).to be_a(Timekeeping::Handoff::LegacySource::Refused)
        expect(error.refusals.fetch(fork_and_leaf.id).join("\n")).to include(orphan.id.to_s)
        expect(error.refusals.fetch(copper_kettle.id).join("\n")).to include(dropped_number.to_s)
        expect(error.refusals.fetch(copper_kettle.id).join("\n")).not_to include(orphan.id.to_s)
      }
  end
end

require "rails_helper"

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  it "export copies a legacy entry audit with its company author time and changes and leaves audits unchanged" do
    connection = ActiveRecord::Base.connection
    entry = TimesheetEntry.joins(project: :client).where(clients: { company_id: fork_and_leaf.id }).order(:id).first
    author = fork_and_leaf.users.order(:id).first
    audited_at = Time.utc(2025, 1, 2, 3, 4, 5)
    audit = Audited::Audit.create!(
      auditable_type: "TimesheetEntry", auditable_id: entry.id, associated_type: "Company",
      associated_id: fork_and_leaf.id, user_type: "User", user_id: author.id, action: "update",
      audited_changes: { "duration" => [1.0, 2.0] }, created_at: audited_at)
    audits_before = connection.select_rows("SELECT * FROM audits ORDER BY id")
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)

    result = described_class.new(connection:, recorded_disposition: recorded)
      .export(generation: 3, captured_at: Time.utc(2026, 10, 25, 12))

    # "Keep its company, author, action, original `created_at` and change values (before and after from `audited_changes`), and set `entry_created_at` from the entry."
    row = result.fetch(:checkpoint).rows.fetch("entry_audits").find { |candidate| candidate["id"] == audit.id }
    expect(row).to include(
      "company_id" => fork_and_leaf.id, "entry_id" => entry.id, "actor_type" => "user", "actor_id" => author.id,
      "action" => "update", "before" => { "duration" => 1.0 }, "after" => { "duration" => 2.0 })
    expect(row["created_at"]).to eq(audited_at)
    expect(row["entry_created_at"]).to eq(entry.reload.created_at)
    # "Never write the legacy `audits` table."
    expect(connection.select_rows("SELECT * FROM audits ORDER BY id")).to eq(audits_before)
  end
end
